import{_ as o,C as a,o as r,c as l,E as n,a2 as s}from"./chunks/framework.vOTwFLKw.js";const f=JSON.parse('{"title":"Free Online Color Palette Generator from One Color","description":"Generate a color palette from a single color online for free. Set hue, saturation, and value with sliders, then build complementary, split complementary, triadic, tetradic, analogous, or monochromatic schemes.","frontmatter":{"title":"Free Online Color Palette Generator from One Color","description":"Generate a color palette from a single color online for free. Set hue, saturation, and value with sliders, then build complementary, split complementary, triadic, tetradic, analogous, or monochromatic schemes.","pageClass":"crop-tool-layout","permalink":"/colorpalette/","canonicalUrl":"https://curvednebula.com/colorpalette/","meta":[{"name":"keywords","content":"color palette generator, complementary colors, color scheme generator, color wheel, hue saturation value, HSV color picker, split complementary, triadic colors, analogous colors, palette from one color"},{"property":"og:title","content":"Free Online Color Palette Generator from One Color"},{"property":"og:description","content":"Pick a base color with hue, saturation, and value sliders and generate a complementary color palette with tints and shades. Copy hex, CSS variables, or JSON."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/colorpalette/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free Online Color Palette Generator from One Color"},{"name":"twitter:description","content":"Build a complementary color palette from a single color. Free, private, and browser-based."}],"aside":false},"headers":[],"relativePath":"colorpalette/index.md","filePath":"colorpalette/index.md"}'),i={name:"colorpalette/index.md"};function h(c,e,d,m,p,u){const t=a("ColorPalette");return r(),l("div",null,[n(t),e[0]||(e[0]=s('<h1 id="create-a-color-palette-from-one-color" tabindex="-1">Create a Color Palette from One Color <a class="header-anchor" href="#create-a-color-palette-from-one-color" aria-label="Permalink to &quot;Create a Color Palette from One Color&quot;">​</a></h1><p>Pick a base color with the hue, saturation, and value sliders — or drop in a hex value — and the generator derives a full palette from it using complementary color theory. Each hue in the scheme comes with five levels, from a pale tint through the base color to a deep shade, so the result is ready to use as design tokens. Copy the hex values, CSS custom properties, or JSON, or save the palette as an image. Everything is calculated in your browser.</p><h2 id="howto" tabindex="-1">Howto <a class="header-anchor" href="#howto" aria-label="Permalink to &quot;Howto&quot;">​</a></h2><ol><li>Set the base color. Drag inside the color wheel to choose a hue and saturation at once, use the <strong>Hue</strong>, <strong>Saturation</strong>, and <strong>Value</strong> sliders for precision, or type a hex value such as <code>#883388</code>.</li><li>Choose a harmony. <strong>Complementary</strong> takes the hue directly opposite the base on the wheel; the other schemes spread the hues differently around the same wheel.</li><li>Choose the color wheel. <strong>RYB</strong> follows traditional artists&#39; color theory, where red pairs with green. <strong>RGB</strong> follows the hue circle used by screens and CSS, where red pairs with cyan.</li><li>Click any swatch to copy its hex value.</li><li>Export the whole palette with <strong>Copy hex list</strong>, <strong>Copy CSS variables</strong>, or <strong>Copy JSON</strong>, or use <strong>Save PNG</strong> for an image of the palette.</li></ol><h2 id="what-complementary-color-theory-does-here" tabindex="-1">What complementary color theory does here <a class="header-anchor" href="#what-complementary-color-theory-does-here" aria-label="Permalink to &quot;What complementary color theory does here&quot;">​</a></h2><p>Complementary colors sit opposite each other on the color wheel. Because they share no common hue, placing them side by side produces the maximum contrast available between two colors — which is exactly why a complementary pair works best when one color dominates and the other is saved for the elements that must be noticed: a button, a highlight, a call to action.</p><p>The other schemes on this page are variations on the same idea. Split complementary trades a little contrast for a lot of comfort by using the two hues either side of the complement. Tetradic uses two complementary pairs at once. Analogous drops complementary contrast entirely in favour of neighbouring hues, and monochromatic works with a single hue, relying on tints and shades alone.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="what-is-a-complementary-color" tabindex="-1">What is a complementary color? <a class="header-anchor" href="#what-is-a-complementary-color" aria-label="Permalink to &quot;What is a complementary color?&quot;">​</a></h3><p>The complementary color is the hue directly opposite your base color on the color wheel, 180 degrees away. On the traditional red-yellow-blue wheel that makes green the complement of red and orange the complement of blue. On the RGB hue circle used by screens, red&#39;s complement is cyan and blue&#39;s is yellow. Both are correct for their own wheel, which is why this tool lets you choose.</p><h3 id="why-do-ryb-and-rgb-give-different-complements" tabindex="-1">Why do RYB and RGB give different complements? <a class="header-anchor" href="#why-do-ryb-and-rgb-give-different-complements" aria-label="Permalink to &quot;Why do RYB and RGB give different complements?&quot;">​</a></h3><p>The two wheels order the hues differently. The red-yellow-blue wheel comes from mixing pigment and is what most color theory teaching is based on; the RGB hue circle comes from mixing light and is what CSS <code>hsl()</code> and every screen uses. Choose RYB when you want the palette to feel like traditional color theory, and RGB when you want the hue offsets to match the values in your code.</p><h3 id="what-is-the-difference-between-saturation-and-value" tabindex="-1">What is the difference between saturation and value? <a class="header-anchor" href="#what-is-the-difference-between-saturation-and-value" aria-label="Permalink to &quot;What is the difference between saturation and value?&quot;">​</a></h3><p>Saturation is how much of the hue is present, from a neutral grey at 0% to the purest form of the color at 100%. Value is how bright the color is, from black at 0% to the brightest version of that hue at 100%. Lowering saturation mutes a color; lowering value darkens it.</p><h3 id="how-are-the-tints-and-shades-generated" tabindex="-1">How are the tints and shades generated? <a class="header-anchor" href="#how-are-the-tints-and-shades-generated" aria-label="Permalink to &quot;How are the tints and shades generated?&quot;">​</a></h3><p>Each hue in the scheme is converted to lightness, then five levels are derived from it: two lighter steps (100 and 300), the base level (500), and two darker steps (700 and 900). Tints are slightly desaturated and shades slightly more saturated, which keeps pale colors from looking washed out and dark colors from looking muddy.</p><h3 id="are-the-palettes-accessible" tabindex="-1">Are the palettes accessible? <a class="header-anchor" href="#are-the-palettes-accessible" aria-label="Permalink to &quot;Are the palettes accessible?&quot;">​</a></h3><p>The tool shows the contrast ratio of your base color against white and black text so you can check it against WCAG requirements — 4.5:1 for normal body text and 3:1 for large text. Swatch labels automatically switch between light and dark for legibility, but always verify the specific color pairs you plan to use.</p><h3 id="is-my-color-data-uploaded-anywhere" tabindex="-1">Is my color data uploaded anywhere? <a class="header-anchor" href="#is-my-color-data-uploaded-anywhere" aria-label="Permalink to &quot;Is my color data uploaded anywhere?&quot;">​</a></h3><p>No. The palette, the color wheel, and the PNG export are all computed locally in your browser. Nothing is sent to a server.</p>',20))])}const w=o(i,[["render",h]]);export{f as __pageData,w as default};
